<?php
declare(strict_types=1); require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/connection.php'; require_alumni();$events=[];$stmt=mysqli_prepare($connection,'SELECT * FROM events_announcements WHERE active=1 AND (event_date>=CURDATE() OR end_date>=CURDATE()) ORDER BY event_date,id');if($stmt){mysqli_stmt_execute($stmt);$r=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($r))$events[]=$row;mysqli_stmt_close($stmt);}$pageTitle='Events & Announcements';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Events | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><section class="hero-banner"><h2>Events & Announcements</h2><p>Stay connected with activities, deadlines, and opportunities.</p></section><div class="event-list"><?php foreach($events as $event):?><article class="event-card"><div class="event-date"><span><?=htmlspecialchars(date('M',strtotime($event['event_date'])))?></span><strong><?=htmlspecialchars(date('d',strtotime($event['event_date'])))?></strong></div><div class="event-content"><span class="tag"><?=htmlspecialchars($event['category']??'Event')?></span><h3><?=htmlspecialchars($event['title'])?></h3><p class="muted"><?=htmlspecialchars($event['location']??'Location to be announced')?> · <?=htmlspecialchars($event['event_time']??'Time to be announced')?></p><p><?=nl2br(htmlspecialchars($event['description']??''))?></p><?php if($event['registration_url']):?><a class="btn btn-primary" target="_blank" rel="noopener" href="<?=htmlspecialchars($event['registration_url'])?>">Learn more</a><?php endif;?></div></article><?php endforeach;if(!$events):?><div class="panel"><p class="muted">No upcoming events yet.</p></div><?php endif;?></div></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
